#include "shared/sea_nuclear_wave.hpp"
#include <vector>
#include <map>
#include <algorithm>
#include <cmath>
#include <limits>
#include <cstdio>
#include <chrono>
using namespace std; struct Bin{float x,z,m=0;vector<size_t> ids;};
void add(SeaNuclearWaveSample&r,const SeaNuclearWave&w,float x,float z){auto s=EvaluateSeaNuclearWave(w,x,z);r.height+=s.height;r.slopeX+=s.slopeX;r.slopeZ+=s.slopeZ;r.foam=max(r.foam,s.foam);r.load=max(r.load,s.load);}
int main(){vector<SeaNuclearWave>w;for(int i=0;i<3600;i++){SeaNuclearWave a{float((i*197)%3000-1500),float((i*311)%3000-1500),0,0,true,float(1+i%10)};a.Advance(1.f+float(i)/60);if(a.active)w.push_back(a);}map<pair<float,float>,size_t>m;vector<Bin> bins;for(size_t i=0;i<w.size();i++){auto&a=w[i];float bx=floor(a.x/1024),bz=floor(a.z/1024);auto [it,ins]=m.emplace(make_pair(bx,bz),bins.size());if(ins)bins.push_back({(bx+.5f)*1024,(bz+.5f)*1024,0,{}});auto&b=bins[it->second];b.m=max(b.m,hypotf(a.x-b.x,a.z-b.z)+a.width*a.lengthScale);b.ids.push_back(i);}for(auto&b:bins)sort(b.ids.begin(),b.ids.end(),[&](size_t a,size_t c){return w[a].Front()<w[c].Front();});double maxh=0,maxs=0,maxfoam=0;int missed=0;size_t checks=0;auto t0=chrono::steady_clock::now();vector<SeaNuclearWaveSample>oracle;for(int p=0;p<3600;p++){float x=-40000+fmodf(p*1373.23f,80000),z=-40000+fmodf(p*911.79f,80000);SeaNuclearWaveSample r;for(auto&a:w)add(r,a,x,z);CompressSeaNuclearWaveSample(r);oracle.push_back(r);}auto t1=chrono::steady_clock::now();for(int p=0;p<3600;p++){float x=-40000+fmodf(p*1373.23f,80000),z=-40000+fmodf(p*911.79f,80000);SeaNuclearWaveSample r;for(auto&b:bins){float d=hypotf(x-b.x,z-b.z),slack=16*numeric_limits<float>::epsilon()*max({1.f,d,abs(x),abs(z),abs(b.x),abs(b.z)}),lo=d-b.m-slack,hi=d+b.m+slack;auto first=lower_bound(b.ids.begin(),b.ids.end(),lo,[&](size_t i,float v){return w[i].Front()<v;}),last=upper_bound(first,b.ids.end(),hi,[&](float v,size_t i){return v<w[i].Front();});for(auto it=first;it!=last;++it){add(r,w[*it],x,z);checks++;}}CompressSeaNuclearWaveSample(r);auto q=oracle[p];maxh=max(maxh,double(abs(q.height-r.height)));maxs=max(maxs,double(hypotf(q.slopeX-r.slopeX,q.slopeZ-r.slopeZ)));maxfoam=max(maxfoam,double(abs(q.foam-r.foam)));missed+=(q.height!=0&&r.height==0);}auto t2=chrono::steady_clock::now();int missing_contributions=0; for(int p=0;p<3600;p++){float x=-40000+fmodf(p*1373.23f,80000),z=-40000+fmodf(p*911.79f,80000);for(auto &b:bins){float d=hypotf(x-b.x,z-b.z),slack=16*numeric_limits<float>::epsilon()*max({1.f,d,abs(x),abs(z),abs(b.x),abs(b.z)}),lo=d-b.m-slack,hi=d+b.m+slack;for(size_t i:b.ids){auto q=EvaluateSeaNuclearWave(w[i],x,z);if((q.height!=0||q.slopeX!=0||q.slopeZ!=0||q.foam!=0) && (w[i].Front()<lo||w[i].Front()>hi))missing_contributions++;}}}printf("missing_individual_contributions=%d\n",missing_contributions);auto ms=[](auto a,auto b){return chrono::duration<double,milli>(b-a).count();};printf("waves=%zu bins=%zu samples=3600 direct_ms=%.3f indexed_ms=%.3f candidates_mean=%.2f height_max_delta=%.8g slope_max_delta=%.8g foam_max_delta=%.8g missing_nonzero=%d\n",w.size(),bins.size(),ms(t0,t1),ms(t1,t2),double(checks)/3600,maxh,maxs,maxfoam,missed);}
